#!/usr/bin/env node
/**
 * Build the browser half: src/client/index.ts -> lib/client.js (single UMD entry).
 *
 * The plugin still ships one browser bundle that only requires react. This
 * script is dev-only; its toolchain lives in tools/build so the plugin keeps
 * zero runtime dependencies and the host junction in node_modules stays intact.
 *
 * The write is atomic (temp file + rename): lib/client.js is the live bundle the
 * running DSH web server serves, so a half-written file would white-screen the
 * panel. Keep that property if you change this script.
 *
 * Optional --entry/--outfile are for fixture tests; defaults stay the shipped
 * src/client/index.ts -> lib/client.js pair.
 */
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const requireFromTools = createRequire(path.join(root, 'tools', 'build', 'package.json'));
const argv = process.argv.slice(2);
function readOption(name) {
  const index = argv.indexOf(name);
  if (index === -1) return null;
  const value = argv[index + 1];
  if (!value || value.startsWith('--')) {
    console.error('[build-client] ' + name + ' needs a value');
    process.exit(1);
  }
  return value;
}
const entryOption = readOption('--entry');
const outfileOption = readOption('--outfile');
if ((entryOption === null) !== (outfileOption === null)) {
  console.error('[build-client] --entry and --outfile must be used together');
  process.exit(1);
}

let esbuild;
try {
  esbuild = requireFromTools('esbuild');
} catch {
  console.error('[build-client] esbuild is missing. Run: npm --prefix tools/build install');
  process.exit(1);
}

const entry = path.resolve(root, entryOption || path.join('src', 'client', 'index.ts'));
const outfile = path.resolve(root, outfileOption || path.join('lib', 'client.js'));
const mapfile = outfile + '.map';

const manifest = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'));
if (typeof manifest.name !== 'string' || !manifest.name.trim()) {
  throw new Error('[build-client] package.json must declare a non-empty name');
}

const prefix = [
  '/* generated by `npm run build:client` from src/client — do not edit */',
  'window.__ModuleLoader__.load({',
  '  id: ' + JSON.stringify(manifest.name) + ',',
  '  factory: function (require) {',
  '    var module = { exports: {} };',
].join('\n');
const suffix = [
  '    return module.exports;',
  '  },',
  '});',
].join('\n');

const result = await esbuild.build({
  entryPoints: [entry],
  outfile,
  bundle: true,
  format: 'cjs',
  platform: 'browser',
  target: ['chrome100', 'firefox100', 'safari15'],
  external: ['react'],
  loader: { '.css': 'text' },
  resolveExtensions: ['.tsx', '.ts', '.jsx', '.js', '.json'],
  jsx: 'transform',
  jsxFactory: 'React.createElement',
  jsxFragment: 'React.Fragment',
  charset: 'utf8',
  keepNames: true,
  minify: false,
  sourcemap: 'external',
  write: false,
  legalComments: 'none',
  banner: { js: prefix },
  footer: { js: suffix },
});

const js = result.outputFiles.find((file) => file.path.endsWith('.js')).text;
const rawMap = result.outputFiles.find((file) => file.path.endsWith('.map')).text;
// Windows checkouts may hold sources with CRLF while CI/worktrees hold LF.
// Normalize only real CRLF characters inside sourcesContent; a literal `\r`
// escape in the source text must survive. Parsing JSON avoids regexes that
// mistake escaped backslashes for line endings.
const parsedMap = JSON.parse(rawMap);
if (Array.isArray(parsedMap.sourcesContent)) {
  parsedMap.sourcesContent = parsedMap.sourcesContent.map((content) =>
    typeof content === 'string' ? content.replace(/\r\n/g, '\n') : content);
}
const map = JSON.stringify(parsedMap, null, 2) + '\n';
const shell = js + '\n//# sourceMappingURL=' + path.basename(mapfile) + '\n';

function atomicWrite(file, data) {
  const temporary = file + '.tmp-' + process.pid;
  fs.writeFileSync(temporary, data);
  try {
    fs.renameSync(temporary, file);
  } catch (error) {
    // Windows can refuse to rename over an open file; fall back to replace.
    fs.rmSync(file, { force: true });
    fs.renameSync(temporary, file);
  }
}

atomicWrite(mapfile, map);
atomicWrite(outfile, shell);

const hash = crypto.createHash('sha256').update(shell).digest('hex').slice(0, 12);
console.log('[build-client] ' + path.relative(root, outfile) + ' ' + Buffer.byteLength(shell) + ' bytes sha256:' + hash);
